static QString t(const wchar_t* s){return QString::fromWCharArray(tr(s));}
static QString bilingual(const char* de,const char* en){return QString::fromUtf8(foto::english?en:de);}
static QImage fromRaster(const foto::Raster& r){if(!r)return {};QImage image(r.rgba.data(),int(r.width),int(r.height),int(r.width)*4,QImage::Format_RGBA8888);return image.convertToFormat(QImage::Format_ARGB32_Premultiplied);}
static std::vector<uint8_t> pixels(const QImage& source){auto image=source.convertToFormat(QImage::Format_ARGB32_Premultiplied);std::vector<uint8_t> result(size_t(image.width())*image.height()*4);for(int y=0;y<image.height();++y)std::memcpy(result.data()+size_t(y)*image.width()*4,image.constScanLine(y),size_t(image.width())*4);return result;}
static QImage rasterImage(std::vector<uint8_t>& data,unsigned w,unsigned h){return QImage(data.data(),int(w),int(h),int(w)*4,QImage::Format_ARGB32_Premultiplied).copy();}
using Operation=std::function<void(std::vector<uint8_t>&,unsigned&,unsigned&)>;
static QImage operate(const QImage& source,const Operation& op){if(source.isNull())return {};auto data=pixels(source);unsigned w=source.width(),h=source.height();op(data,w,h);return rasterImage(data,w,h);}
static QString toolPath(const QString& name){QString bundled=QCoreApplication::applicationDirPath()+"/"+name;if(QFileInfo(bundled).isExecutable())return bundled;QString system="/usr/bin/"+name;if(QFileInfo(system).isExecutable())return system;return QStandardPaths::findExecutable(name);}
static bool runTool(const QString& program,const QStringList& arguments,int timeout=15000,QByteArray* result=nullptr){if(program.isEmpty())return false;QProcess process;QProcessEnvironment env=QProcessEnvironment::systemEnvironment();env.insert("MAGICK_THREAD_LIMIT","2");env.insert("OMP_NUM_THREADS","2");process.setProcessEnvironment(env);process.setChildProcessModifier([]{struct rlimit memory{768ull*1024*1024,768ull*1024*1024},disk{256ull*1024*1024,256ull*1024*1024},cpu{20,20};setrlimit(RLIMIT_AS,&memory);setrlimit(RLIMIT_FSIZE,&disk);setrlimit(RLIMIT_CPU,&cpu);});process.start(program,arguments);if(!process.waitForStarted(3000)||!process.waitForFinished(timeout)){process.kill();process.waitForFinished(1000);return false;}if(result)*result=process.readAllStandardOutput();return process.exitStatus()==QProcess::NormalExit&&process.exitCode()==0;}
static QImage loadImage(const QString& file,int edge=6000){if(!QFileInfo(file).isFile()||QFileInfo(file).size()>512ll*1024*1024)return {};QImageReader reader(file);reader.setAutoTransform(true);QSize size=reader.size();if(size.isValid()&&(size.width()>edge||size.height()>edge))reader.setScaledSize(size.scaled(edge,edge,Qt::KeepAspectRatio));auto image=reader.read();if(!image.isNull())return image.convertToFormat(QImage::Format_ARGB32_Premultiplied);
 QFile input(file);if((edge>256||input.size()<64ll*1024*1024)&&input.open(QIODevice::ReadOnly)){auto bytes=input.readAll();auto decoded=foto::embedded(std::vector<uint8_t>(bytes.begin(),bytes.end()),QFileInfo(file).suffix().toLower().toStdString());if(decoded){image=fromRaster(decoded);if(std::max(image.width(),image.height())>edge)image=image.scaled(edge,edge,Qt::KeepAspectRatio,Qt::SmoothTransformation);return image;}}
 QTemporaryDir temp;if(!temp.isValid())return {};QString output=temp.filePath("preview.png"),ext=QFileInfo(file).suffix().toLower();bool good=false;
 if(ext=="pdf")good=runTool(toolPath("pdftoppm"),{"-f","1","-singlefile","-scale-to",QString::number(edge),"-png",file,temp.filePath("preview")});
 else if(ext=="ps"||ext=="eps"||ext=="epsf"||ext=="epsi")good=runTool(toolPath("gs"),{"-dSAFER","-dBATCH","-dNOPAUSE","-dEPSCrop","-dFirstPage=1","-dLastPage=1","-sDEVICE=pngalpha","-r96","-sOutputFile="+output,file});
 else if(ext=="jxl"){good=runTool(toolPath("PAFPhotos.JXL"),{file,output});if(!good)good=runTool(toolPath("djxl"),{file,output,"--num_threads=2"});}
 if(!good){auto magick=toolPath("magick");if(magick.isEmpty())magick=toolPath("convert");good=runTool(magick,{"-limit","memory","128MiB","-limit","map","256MiB","-limit","disk","256MiB","-limit","thread","2",file+"[0]","-auto-orient","-thumbnail",QString::number(edge)+"x"+QString::number(edge)+">",output});}
 if(!good){const QStringList raw={"raw","dng","cr2","cr3","crw","nef","nrw","arw","srf","sr2","raf","orf","rw2","rw1","pef","ptx","3fr","fff","iiq","k25","kdc","dcr","mos","mrw","mef","erf","cap","eip","bay","rwl","srw","x3f"};if(raw.contains(ext)){QByteArray bytes;good=runTool(toolPath("dcraw_emu"),{"-h","-T","-c","-w",file},15000,&bytes);if(good&&bytes.size()<256*1024*1024){output=temp.filePath("raw.tiff");QFile rawOutput(output);if(rawOutput.open(QIODevice::WriteOnly))rawOutput.write(bytes);else good=false;}else good=false;}}if(good){QImageReader result(output);image=result.read();if(!image.isNull())return image.convertToFormat(QImage::Format_ARGB32_Premultiplied);}return {};}
static bool saveImage(const QImage& image,const QString& original,QString target,const QByteArray& format,int quality=95){if(image.isNull())return false;auto canonical=QFileInfo(original).canonicalFilePath(),dest=QFileInfo(target).canonicalFilePath();if(!canonical.isEmpty()&&(canonical==dest||QFileInfo(original).absoluteFilePath()==QFileInfo(target).absoluteFilePath()))return false;QSaveFile output(target);if(!output.open(QIODevice::WriteOnly))return false;QImageWriter writer(&output,format);writer.setQuality(quality);QImage saved=image;if(format=="jpg"||format=="jpeg"){saved=QImage(image.size(),QImage::Format_RGB32);saved.fill(Qt::white);QPainter p(&saved);p.drawImage(0,0,image);}if(!writer.write(saved))return false;return output.commit();}
