class SmoothSlider:public QSlider{public:QColor accent;SmoothSlider(Qt::Orientation orientation,QColor color):QSlider(orientation),accent(color){setMinimumHeight(32);setFocusPolicy(Qt::StrongFocus);}
 void paintEvent(QPaintEvent*)override{QPainter p(this);p.setRenderHint(QPainter::Antialiasing);p.fillRect(rect(),palette().color(QPalette::Window));double fraction=double(value()-minimum())/std::max(1,maximum()-minimum());double x=12+(width()-24)*fraction,y=height()/2.0;p.setPen(Qt::NoPen);p.setBrush(palette().color(QPalette::Mid));p.drawRoundedRect(QRectF(12,y-2,width()-24,4),2,2);p.setBrush(accent);p.drawRoundedRect(QRectF(12,y-2,std::max(0.0,x-12),4),2,2);p.setBrush(palette().color(QPalette::Mid));p.drawEllipse(QPointF(x,y),11,11);p.setBrush(accent);p.drawEllipse(QPointF(x,y),7,7);if(hasFocus()){p.setBrush(Qt::NoBrush);p.setPen(QPen(palette().color(QPalette::WindowText),1,Qt::DotLine));p.drawEllipse(QPointF(x,y),10,10);}}
 void position(QMouseEvent* e){int position=minimum()+qRound(std::clamp((e->position().x()-12)/std::max(1,width()-24),0.0,1.0)*(maximum()-minimum()));setValue(position);update();}
 void mousePressEvent(QMouseEvent* e)override{if(e->button()!=Qt::LeftButton)return;setFocus();setSliderDown(true);grabMouse();position(e);}
 void mouseMoveEvent(QMouseEvent* e)override{if(isSliderDown())position(e);}
 void mouseReleaseEvent(QMouseEvent* e)override{if(!isSliderDown())return;position(e);setSliderDown(false);releaseMouse();update();}
 void wheelEvent(QWheelEvent* e)override{e->ignore();}
};
class Canvas:public QWidget{
public:QImage image,original;bool compare=false,editing=false;int tool=0;double zoom=1;bool actual=false;QPointF pan;QRectF crop{0,0,1,1};double ratio=0;QColor accent{48,180,240},background{24,28,36},strokeColor{255,88,96};int brushSize=12;paf::BrushKind brush=paf::BrushKind::Pen;bool backgroundBrush=false;QSize logicalSize;QRectF box;QPoint down;QPointF startPan;QRectF startCrop;int handle=-1;bool dragging=false,drawing=false;std::vector<paf::BrushPoint> points;std::function<void(std::vector<paf::BrushPoint>)> finished;
 Canvas(){setMinimumSize(180,180);setFocusPolicy(Qt::StrongFocus);setMouseTracking(true);setAttribute(Qt::WA_OpaquePaintEvent);}
 void paintEvent(QPaintEvent*)override{QPainter p(this);p.fillRect(rect(),background);p.setRenderHint(QPainter::Antialiasing);p.setRenderHint(QPainter::SmoothPixmapTransform);auto shown=compare?original:image;if(shown.isNull())return;QSize logical=editing&&!compare&&logicalSize.isValid()?logicalSize:shown.size();double fit=std::min((width()-40.0)/logical.width(),(height()-40.0)/logical.height());double factor=actual?zoom:fit;QSizeF size=logical*factor;box=QRectF(QPointF((width()-size.width())/2,(height()-size.height())/2)+pan,size);
 if(shown.hasAlphaChannel()){p.save();p.setClipRect(box);for(int y=int(box.top());y<box.bottom();y+=16)for(int x=int(box.left());x<box.right();x+=16)p.fillRect(QRect(x,y,16,16),((x-int(box.left()))/16+(y-int(box.top()))/16)%2?QColor(48,54,64):QColor(66,72,82));p.restore();}p.drawImage(box,shown);
 if(editing&&tool==0&&!compare){QRectF selection(box.left()+crop.left()*box.width(),box.top()+crop.top()*box.height(),crop.width()*box.width(),crop.height()*box.height());QPainterPath shade;shade.addRect(box);shade.addRect(selection);shade.setFillRule(Qt::OddEvenFill);p.fillPath(shade,QColor(0,0,0,90));p.setPen(QPen(Qt::white,1.5));p.drawRect(selection);p.setPen(QColor(255,255,255,70));for(int i=1;i<3;++i){p.drawLine(QPointF(selection.left()+selection.width()*i/3,selection.top()),QPointF(selection.left()+selection.width()*i/3,selection.bottom()));p.drawLine(QPointF(selection.left(),selection.top()+selection.height()*i/3),QPointF(selection.right(),selection.top()+selection.height()*i/3));}p.setBrush(Qt::white);p.setPen(Qt::NoPen);for(auto point:handles(selection))p.drawRect(QRectF(point-QPointF(3,3),QSizeF(6,6)));}
 if(drawing&&!points.empty()){QPen pen(strokeColor,brushSize*factor,Qt::SolidLine,Qt::RoundCap,Qt::RoundJoin);if(brush==paf::BrushKind::Highlighter){auto color=strokeColor;color.setAlpha(85);pen.setColor(color);}p.setPen(pen);for(size_t i=1;i<points.size();++i)p.drawLine(QPointF(box.x()+points[i-1].x*factor,box.y()+points[i-1].y*factor),QPointF(box.x()+points[i].x*factor,box.y()+points[i].y*factor));}}
 QList<QPointF> handles(const QRectF& r){return {r.topLeft(),QPointF(r.center().x(),r.top()),r.topRight(),QPointF(r.right(),r.center().y()),r.bottomRight(),QPointF(r.center().x(),r.bottom()),r.bottomLeft(),QPointF(r.left(),r.center().y())};}
 QPointF imagePoint(const QPointF& point){return {(point.x()-box.x())/box.width()*(logicalSize.isValid()?logicalSize.width():image.width()),(point.y()-box.y())/box.height()*(logicalSize.isValid()?logicalSize.height():image.height())};}
 void mousePressEvent(QMouseEvent* e)override{if(e->button()!=Qt::LeftButton||image.isNull())return;setFocus();down=e->pos();startPan=pan;startCrop=crop;handle=-1;drawing=editing&&(tool==3||tool==4||(tool==5&&backgroundBrush));if(drawing){auto q=imagePoint(e->position());points={{q.x(),q.y()}};}else if(editing&&tool==0){QRectF r(box.x()+crop.x()*box.width(),box.y()+crop.y()*box.height(),crop.width()*box.width(),crop.height()*box.height());auto h=handles(r);for(int i=0;i<h.size();++i)if(QLineF(h[i],e->position()).length()<12)handle=i;if(handle<0&&r.contains(e->position()))handle=8;}dragging=true;grabMouse();update();}
 void mouseMoveEvent(QMouseEvent* e)override{if(!dragging)return;if(drawing){auto q=imagePoint(e->position());points.push_back({q.x(),q.y()});}else if(editing&&tool==0&&handle>=0){QPointF delta((e->position().x()-down.x())/box.width(),(e->position().y()-down.y())/box.height());auto r=startCrop;if(handle==8)r.moveTopLeft({std::clamp(r.x()+delta.x(),0.0,1-r.width()),std::clamp(r.y()+delta.y(),0.0,1-r.height())});else{if(handle==0||handle==6||handle==7)r.setLeft(std::clamp(r.left()+delta.x(),0.0,r.right()-.02));if(handle==2||handle==3||handle==4)r.setRight(std::clamp(r.right()+delta.x(),r.left()+.02,1.0));if(handle==0||handle==1||handle==2)r.setTop(std::clamp(r.top()+delta.y(),0.0,r.bottom()-.02));if(handle==4||handle==5||handle==6)r.setBottom(std::clamp(r.bottom()+delta.y(),r.top()+.02,1.0));if(ratio>0){double normalized=ratio*image.height()/image.width();r.setHeight(r.width()/normalized);if(r.bottom()>1){r.setHeight(1-r.top());r.setWidth(r.height()*normalized);}}}crop=r;}else pan=startPan+e->position()-down;update();}
 void mouseReleaseEvent(QMouseEvent*)override{if(drawing&&finished)finished(points);drawing=dragging=false;points.clear();releaseMouse();update();}
 void wheelEvent(QWheelEvent* e)override{if(image.isNull())return;if(!actual)zoom=std::min((width()-40.0)/image.width(),(height()-40.0)/image.height());actual=true;zoom=std::clamp(zoom*std::pow(1.0015,e->angleDelta().y()),.02,16.0);update();}
 void keyPressEvent(QKeyEvent* e)override{if(e->key()==Qt::Key_Space){compare=true;update();}else QWidget::keyPressEvent(e);}void keyReleaseEvent(QKeyEvent* e)override{if(e->key()==Qt::Key_Space){compare=false;update();}else QWidget::keyReleaseEvent(e);}
};
