 void trimHistory(){qsizetype memory=0;for(const auto& state:undo)memory+=state.sizeInBytes();while(undo.size()>1&&(undo.size()>20||memory>192*1024*1024)){memory-=undo.first().sizeInBytes();undo.removeFirst();}}
 QIcon symbol(QString code){QPixmap pixmap(48,48);pixmap.fill(Qt::transparent);QPainter p(&pixmap);p.scale(2,2);p.setRenderHint(QPainter::Antialiasing);p.setPen(QPen(theme=="light"?QColor("#19202a"):QColor("#f3f5fa"),1.6,Qt::SolidLine,Qt::RoundCap,Qt::RoundJoin));if(code=="+"||code=="−"){p.drawLine(6,12,18,12);if(code=="+")p.drawLine(12,6,12,18);}else if(code=="☀"){p.drawEllipse(QPoint(12,12),4,4);for(int i=0;i<8;++i){double a=i*3.14159265359/4;p.drawLine(QPointF(12+7*cos(a),12+7*sin(a)),QPointF(12+10*cos(a),12+10*sin(a)));}}else if(code=="▣"||code=="▧"){p.drawRect(QRect(6,6,12,12));p.drawLine(3,6,21,6);p.drawLine(6,3,6,21);}else if(code=="✎"){p.drawLine(5,18,17,5);p.drawLine(7,20,20,7);p.drawLine(5,18,7,20);p.drawLine(17,5,20,7);}else if(code=="◇"){p.drawPolygon(QPolygonF({{4,12},{12,4},{20,12},{12,20}}));p.drawLine(8,16,16,8);}else if(code=="☰"){for(int y:{6,12,18})p.drawLine(5,y,19,y);}else if(code=="▦"||code=="▥"||code=="▨"){p.drawRect(QRect(4,4,16,16));for(int x:{8,12,16})p.drawLine(x,5,code=="▨"?x+3:x,19);}else if(code=="▱"){p.drawPolyline(QPolygonF({{3,19},{3,7},{10,7},{12,10},{21,10},{21,19},{3,19}}));}else if(code=="ⓘ"){p.drawEllipse(QRect(4,4,16,16));p.drawLine(12,10,12,16);p.drawPoint(12,7);}else if(code=="♡"){QPainterPath heart;heart.moveTo(12,20);heart.cubicTo(2,13,2,4,8,5);heart.quadTo(10,5,12,8);heart.quadTo(14,5,17,5);heart.cubicTo(22,5,23,13,12,20);p.drawPath(heart);}else if(code=="↶"||code=="↷"){p.drawArc(QRect(5,5,14,14),code=="↶"?20*16:160*16,270*16);int x=code=="↶"?5:19;p.drawLine(x,5,x,11);p.drawLine(x,11,x+(code=="↶"?5:-5),11);}else if(code=="⇄"||code=="←"||code=="→"){p.drawLine(4,10,20,10);int head=code=="→"?20:4,tail=code=="→"?16:8;p.drawLine(head,10,tail,6);p.drawLine(head,10,tail,14);if(code=="⇄"){p.drawLine(4,16,20,16);p.drawLine(20,16,16,12);p.drawLine(20,16,16,20);}}else if(code=="↕"){p.drawLine(12,4,12,20);p.drawLine(12,4,8,8);p.drawLine(12,4,16,8);p.drawLine(12,20,8,16);p.drawLine(12,20,16,16);}else if(code=="▶"){p.drawPolygon(QPolygonF({{7,5},{19,12},{7,19}}));}else{p.drawEllipse(QRect(5,5,14,14));p.drawLine(12,3,12,6);p.drawLine(12,18,12,21);p.drawLine(3,12,6,12);p.drawLine(18,12,21,12);}p.end();pixmap.setDevicePixelRatio(2);return QIcon(pixmap);}
